class MyHashMap:
    def __init__(self):
        self.bucket_count = 1009                                  # a modest fixed number of buckets
        self.buckets = [[] for _ in range(self.bucket_count)]

    def _hash(self, key):
        return key % self.bucket_count

    def put(self, key, value):
        bucket = self.buckets[self._hash(key)]
        for i, (k, v) in enumerate(bucket):
            if k == key:
                bucket[i] = (key, value)                              # update an existing key in this bucket
                return
        bucket.append((key, value))                                     # append a brand new key to this bucket

    def get(self, key):
        bucket = self.buckets[self._hash(key)]
        for k, v in bucket:
            if k == key:
                return v
        return -1

    def remove(self, key):
        bucket = self.buckets[self._hash(key)]
        for i, (k, v) in enumerate(bucket):
            if k == key:
                bucket.pop(i)
                return


