import java.util.*;

public class Main {
    class MyHashMap {
        int bucketCount = 1009;                                          // a modest fixed number of buckets
        List<List<int[]>> buckets = new ArrayList<>();

        public MyHashMap() {
            for (int i = 0; i < bucketCount; i++) buckets.add(new ArrayList<>());
        }

        int hash(int key) {
            return key % bucketCount;
        }

        public void put(int key, int value) {
            List<int[]> bucket = buckets.get(hash(key));
            for (int[] pair : bucket) {
                if (pair[0] == key) { pair[1] = value; return; }               // update an existing key in this bucket
            }
            bucket.add(new int[]{key, value});                                   // append a brand new key to this bucket
        }

        public int get(int key) {
            List<int[]> bucket = buckets.get(hash(key));
            for (int[] pair : bucket) {
                if (pair[0] == key) return pair[1];
            }
            return -1;
        }

        public void remove(int key) {
            List<int[]> bucket = buckets.get(hash(key));
            bucket.removeIf(pair -> pair[0] == key);
        }
    }

    public static void main(String[] args) {
        MyHashMap hashMap = new MyHashMap();
        hashMap.put(1, 1);
        hashMap.put(2, 2);
        System.out.println(hashMap.get(1));
        System.out.println(hashMap.get(3));
        hashMap.put(2, 1);
        System.out.println(hashMap.get(2));
        hashMap.remove(2);
        System.out.println(hashMap.get(2));
    }
}

