#include <bits/stdc++.h>
using namespace std;

class MyHashMap {
public:
    int bucketCount = 1009;                                            // a modest fixed number of buckets
    vector<list<pair<int, int>>> buckets;

    MyHashMap() : buckets(bucketCount) {}

    int hashKey(int key) {
        return key % bucketCount;
    }

    void put(int key, int value) {
        auto& bucket = buckets[hashKey(key)];
        for (auto& entry : bucket) {
            if (entry.first == key) { entry.second = value; return; }         // update an existing key in this bucket
        }
        bucket.push_back({key, value});                                         // append a brand new key to this bucket
    }

    int get(int key) {
        auto& bucket = buckets[hashKey(key)];
        for (auto& entry : bucket) {
            if (entry.first == key) return entry.second;
        }
        return -1;
    }

    void remove(int key) {
        auto& bucket = buckets[hashKey(key)];
        bucket.remove_if([key](const pair<int, int>& entry) { return entry.first == key; });
    }
};

int main() {
    MyHashMap hashMap;
    hashMap.put(1, 1);
    hashMap.put(2, 2);
    cout << hashMap.get(1) << endl;
    cout << hashMap.get(3) << endl;
    hashMap.put(2, 1);
    cout << hashMap.get(2) << endl;
    hashMap.remove(2);
    cout << hashMap.get(2) << endl;
    return 0;
}
